// Load the namespaces
using namespace std;
using json = nlohmann::json;

// Minimal OSC 1.0 encoder: JSON keypaths become OSC addresses
namespace Osc {

static void put_str(string &buf, string const &s) {
  buf += s;
  buf.append(4 - s.size() % 4, '\0'); // NUL-terminate, pad to 4 bytes
}

static void put_be(string &buf, uint64_t v, int bytes) {
  for (int i = bytes - 1; i >= 0; --i)
    buf += char((v >> (8 * i)) & 0xFF);
}

static bool is_scalar(json const &j) { return j.is_primitive() && !j.is_null(); }

// args is a JSON array of scalars
static string message(string const &address, json const &args) {
  string tags = ",", data;
  for (auto const &a : args) {
    if (a.is_boolean()) {
      tags += a.get<bool>() ? 'T' : 'F';
    } else if (a.is_number_float()) {
      float f = a.get<float>();
      uint32_t u;
      memcpy(&u, &f, 4);
      tags += 'f';
      put_be(data, u, 4);
    } else if (a.is_number_integer()) {
      int64_t i = a.get<int64_t>();
      if (i >= INT32_MIN && i <= INT32_MAX) {
        tags += 'i';
        put_be(data, uint32_t(int32_t(i)), 4);
      } else {
        tags += 'h';
        put_be(data, uint64_t(i), 8);
      }
    } else if (a.is_string()) {
      tags += 's';
      put_str(data, a.get<string>());
    }
  }
  string msg;
  put_str(msg, address);
  put_str(msg, tags);
  return msg + data;
}

// One message per scalar leaf; an all-scalar array is one multi-arg message
// (maps onto Blender vector properties). Nulls are skipped.
// shortcut: keys are not sanitized for OSC-reserved chars (space # * ? [ ] { }
// , /), sanitize if upstream frames use such keys.
static void flatten(json const &j, string const &path, vector<string> &out) {
  if (is_scalar(j)) {
    out.push_back(message(path, json::array({j})));
  } else if (j.is_array() && !j.empty() &&
             all_of(j.begin(), j.end(), is_scalar)) {
    out.push_back(message(path, j));
  } else if (j.is_structured()) {
    for (auto const &[k, v] : j.items())
      flatten(v, path + "/" + k, out);
  }
}

} // namespace Osc

static void net_init() {
#ifdef _WIN32
  WSADATA wsa;
  WSAStartup(MAKEWORD(2, 2), &wsa);
#endif
}


// Plugin class: sends every incoming frame to NodeOSC as flat OSC messages
class BlenderPlugin : public Sink<json> {

public:
  using Sink::Sink; // inherit constructors

  ~BlenderPlugin() {
    if (_sock != INVALID_SOCKET)
      close_socket(_sock);
  }

  string kind() override { return PLUGIN_NAME; }

  return_type load_data(json const &input, string topic = "", vector<unsigned char> const *blob = nullptr) override {
    if (_sock == INVALID_SOCKET)
      return return_type::critical; // _error set by set_params()
    try {
      vector<string> msgs;
      Osc::flatten(input, _params["use_topic"].get<bool>() ? "/" + topic : "",
                   msgs);
      for (auto const &m : msgs) {
        if (sendto(_sock, m.data(), int(m.size()), 0,
                   (sockaddr const *)&_addr, _addr_len) < 0) {
          _error = "cannot send OSC message to " + _endpoint;
          return return_type::error;
        }
      }
      return return_type::success;
    } catch (exception const &e) {
      _error = e.what();
      return return_type::error;
    }
  }

  void set_params(const json &params) override {
    Sink::set_params(params);
    _params["host"] = "127.0.0.1";
    _params["port"] = 9001; // NodeOSC default input port
    _params["use_topic"] = false;
    _params.merge_patch(params);

    try {
      string host = _params["host"].get<string>();
      int port = _params["port"].get<int>();
      (void)_params["use_topic"].get<bool>(); // validate type now, not per frame
      if (port < 1 || port > 65535)
        throw runtime_error("port out of range: " + to_string(port));
      _endpoint = host + ":" + to_string(port);

      net_init();
      addrinfo hints{}, *res = nullptr;
      hints.ai_family = AF_UNSPEC;
      hints.ai_socktype = SOCK_DGRAM;
      if (getaddrinfo(host.c_str(), to_string(port).c_str(), &hints, &res) != 0 || !res)
        throw runtime_error("cannot resolve " + _endpoint);
      memcpy(&_addr, res->ai_addr, res->ai_addrlen);
      _addr_len = socklen_t(res->ai_addrlen);
      _sock = socket(res->ai_family, SOCK_DGRAM, IPPROTO_UDP);
      freeaddrinfo(res);
      if (_sock == INVALID_SOCKET)
        throw runtime_error("cannot open UDP socket");
    } catch (exception const &e) {
      _error = string("blender: ") + e.what();
    }
  }

  map<string, string> info() override {
    return {{"OSC endpoint", _endpoint},
            {"Topic in address", _params["use_topic"].get<bool>() ? "yes" : "no"}};
  };

private:
  socket_t _sock = INVALID_SOCKET;
  sockaddr_storage _addr{};
  socklen_t _addr_len = 0;
  string _endpoint;
};



